select set_config('test.batch',private.stage_synthetic_migration(pg_temp.payload(),'Synthetic review fixture v1'),true);

select is(private.stage_synthetic_migration(pg_temp.payload(),'Synthetic review fixture v1'),current_setting('test.batch'),'Exact staging retry is a no-op');
select is((private.apply_synthetic_migration(current_setting('test.batch'),1)->>'remaining')::int,4,'First bounded checkpoint imports one family');
select is((private.apply_synthetic_migration(current_setting('test.batch'),1)->>'remaining')::int,3,'Resume imports child with same family reference');
select is((private.apply_synthetic_migration(current_setting('test.batch'),100)->>'remaining')::int,0,'Remaining mapped snapshot rows imported');
select is((private.apply_synthetic_migration(current_setting('test.batch'),100)->>'applied')::int,0,'Exact apply replay makes no new writes');
select is((private.reconcile_synthetic_migration(current_setting('test.batch'))->>'openingMinor')::bigint,1001::bigint,'Opening balance preserves exact minor units');
select is((private.reconcile_synthetic_migration(current_setting('test.batch'))->>'historicalNetMinor')::bigint,2520::bigint,'Historical payment remains separate from opening');
select is((private.reconcile_synthetic_migration(current_setting('test.batch'))->>'remainingSessions')::int,4,'Imported entitlement snapshot reconciles');
select is((select count(*)::int from public.commercial_payments),0,'Historical imports create no new collections');
select throws_ok($$select private.stage_synthetic_migration(jsonb_set(pg_temp.payload(),'{rows,0,value,name}','"Changed source name"'),'Synthetic changed source')$$,'22023',null,'Payload mutation cannot reuse original fingerprint');
