select throws_ok($$select private.reverse_synthetic_migration(current_setting('test.batch'))$$,'P0409',null,'Downstream edit blocks destructive batch reversal');
update public.families set name='Synthetic imported family' where id='8c732745-0323-5c98-a6a0-134e8cb54427';
select is((private.reverse_synthetic_migration(current_setting('test.batch'))->>'reversed')::int,5,'Own-batch reversal removes only untouched imported data');
select is((select count(*)::int from public.families where id='a3300000-0000-4000-8000-000000000001'),1,'Unrelated existing family survives reversal');
select is((private.reverse_synthetic_migration(current_setting('test.batch'))->>'reversed')::int,0,'Reversal retry is idempotent');
select throws_ok($$select private.apply_synthetic_migration(current_setting('test.batch'),100)$$,'P0409',null,'Reversed batch cannot silently reapply');
select is((select count(*)::int from private.migration_rows),5,'Owned change manifest retained after reversal');
